//! Resolves bounded-storage compile-time knobs and emits constants into OUT_DIR/config.rs.
use std::collections::HashMap;
use std::fmt::Write;
use std::path::PathBuf;
use std::{env, fs};

/// Known setting names and defaults; environment values override matching numeric features.
static CONFIGS: &[(&str, usize)] = &[
    // BEGIN AUTOGENERATED CONFIG FEATURES
    // Generated by gen_config.py. DO NOT EDIT.
    ("CONNECTION_EVENT_QUEUE_SIZE", 2),
    ("L2CAP_RX_QUEUE_SIZE", 8),
    ("L2CAP_TX_QUEUE_SIZE", 8),
    ("DEFAULT_PACKET_POOL_SIZE", 16),
    ("DEFAULT_PACKET_POOL_MTU", 251),
    ("GATT_CLIENT_NOTIFICATION_MAX_SUBSCRIBERS", 1),
    ("GATT_CLIENT_NOTIFICATION_QUEUE_SIZE", 1),
    ("CLIENT_ATT_TABLE_SIZE", 64),
    ("PREPARE_WRITE_BUFFER_SIZE", 512),
    // END AUTOGENERATED CONFIG FEATURES
];

/// Resolution state for one knob while scanning Cargo/process environment variables.
struct ConfigState {
    /// Selected count or byte capacity, not range-validated by this script.
    value: usize,
    /// A numeric feature supplied this setting, even if an explicit value overrides it.
    seen_feature: bool,
    /// An explicit crate-prefixed environment value was observed.
    seen_env: bool,
}

/// Generates selected constants and Cargo rebuild directives from package name, features and environment.
/// Panics on unknown prefixed settings, invalid integers, conflicting features, missing Cargo paths or I/O failure.
fn main() {
    let crate_name = env::var("CARGO_PKG_NAME")
        .unwrap()
        .to_ascii_uppercase()
        .replace('-', "_");

    // We don't use any external files: only run the build script if it has changed.
    // Otherwise, Cargo will re-run it on each build.
    println!("cargo::rerun-if-changed=build.rs");

    println!("cargo::rustc-check-cfg=cfg(test)");

    // Check feature usage.
    //
    // Helps both document inter-feature relations, and stop builds ASAP if invariants are not
    // fulfilled. For the developer, this leads to more straightforward error messages.
    //
    // Reference: Cargo features > https://embassy.dev/trouble/#_cargo_features
    {
        // 'scan' needs 'central'
        #[cfg(all(feature = "scan", not(feature = "central")))]
        compile_error!("Feature 'scan' also needs 'central' to be enabled.");

        // Also in 'fmt.rs'
        #[cfg(all(feature = "defmt", feature = "log"))]
        compile_error!("You may not enable both `defmt` and `log` features.");

        // Also in 'lib.rs'
        #[cfg(not(any(feature = "central", feature = "peripheral")))]
        compile_error!("Must enable at least one of: `central`, `peripheral`");

        //...

        // Only one of (or none) 'default-packet-pool-size-{X}' is allowed
        {
            let n = 0;
            #[cfg(feature = "default-packet-pool-size-1")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-2")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-4")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-8")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-16")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-32")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-64")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-size-128")]
            let n = n + 1;

            assert!(
                n <= 1,
                "📍 More than one 'default-packet-pool-size-X' feature is enabled."
            );

            #[cfg(not(feature = "default-packet-pool"))]
            if n > 0 {
                panic!("📍 'default-packet-pool-size-{{X}}' feature also needs 'default-packet-pool' to be enabled.");
            }
        }

        // Only one of (or none) 'default-packet-pool-mtu-{X}' is allowed
        {
            let n = 0;
            #[cfg(feature = "default-packet-pool-mtu-27")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-48")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-64")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-128")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-251")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-255")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-512")]
            let n = n + 1;
            #[cfg(feature = "default-packet-pool-mtu-1024")]
            let n = n + 1;

            assert!(
                n <= 1,
                "📍 More than one 'default-packet-pool-mtu-X' feature is enabled."
            );

            #[cfg(not(feature = "default-packet-pool"))]
            if n > 0 {
                panic!("📍 'default-packet-pool-mtu-{{X}}' feature also needs 'default-packet-pool' to be enabled.");
            }
        }
    }

    // Rebuild if config envvar changed.
    for (name, _) in CONFIGS {
        println!("cargo::rerun-if-env-changed={crate_name}_{name}");
    }

    let configs = resolve_configs(&crate_name, env::vars());

    let mut data = String::new();

    for (name, cfg) in &configs {
        writeln!(
            &mut data,
            "#[doc = {:?}]\npub const {}: usize = {};",
            config_doc(name),
            name,
            cfg.value
        )
        .unwrap();
    }

    // A notification holds at most `ATT_MTU - 3` bytes, and `ATT_MTU` here is `PacketPool::MTU - 4`.
    // When the default-packet-pool-mtu-* is not set, use 512, which is the largest allowed value.
    let pool = &configs["DEFAULT_PACKET_POOL_MTU"];
    let notification_mtu = if pool.seen_feature || pool.seen_env {
        pool.value.saturating_sub(7).min(512)
    } else {
        512
    };
    writeln!(
        &mut data,
        "/// Maximum queued notification payload bytes; explicit pool MTU minus seven, saturated and capped at 512.\npub const GATT_CLIENT_NOTIFICATION_MTU: usize = {};",
        notification_mtu
    )
    .unwrap();

    let out_dir = PathBuf::from(env::var_os("OUT_DIR").unwrap());
    let out_file = out_dir.join("config.rs").to_string_lossy().to_string();
    fs::write(out_file, data).unwrap();
}

/// Returns the unit/ownership contract for generated setting `name`; unknown names panic.
fn config_doc(name: &str) -> &'static str {
    match name {
        "CONNECTION_EVENT_QUEUE_SIZE" => "Maximum queued events per connection.",
        "L2CAP_RX_QUEUE_SIZE" => "Maximum queued incoming packets per L2CAP channel.",
        "L2CAP_TX_QUEUE_SIZE" => "Maximum queued outgoing L2CAP packets shared by the host.",
        "DEFAULT_PACKET_POOL_SIZE" => "Number of packet buffers in the default shared pool.",
        "DEFAULT_PACKET_POOL_MTU" => "Byte capacity of each default packet buffer, including the L2CAP header.",
        "GATT_CLIENT_NOTIFICATION_MAX_SUBSCRIBERS" => "Maximum simultaneous subscribers to client notifications.",
        "GATT_CLIENT_NOTIFICATION_QUEUE_SIZE" => "Maximum queued GATT client notifications.",
        "CLIENT_ATT_TABLE_SIZE" => "Per-connection byte capacity for client-specific attribute values.",
        "PREPARE_WRITE_BUFFER_SIZE" => "Per-connection byte capacity for queued ATT Prepare Write data.",
        _ => panic!("unknown generated setting {name}"),
    }
}

/// Returns selected settings for package prefix `crate_name` from owned environment `vars`.
/// Features are validated first, then explicit values override them; iteration order cannot hide conflicts.
/// Panics on unknown prefixed names, invalid integers and conflicting numeric features.
fn resolve_configs(
    crate_name: &str,
    vars: impl IntoIterator<Item = (String, String)>,
) -> HashMap<&'static str, ConfigState> {
    let mut configs = HashMap::new();
    for (name, default) in CONFIGS {
        configs.insert(
            *name,
            ConfigState {
                value: *default,
                seen_env: false,
                seen_feature: false,
            },
        );
    }

    // Validate feature selection independently of platform environment iteration order.
    let vars: Vec<_> = vars.into_iter().collect();
    for (var, _) in &vars {
        if let Some(feature) = var.strip_prefix("CARGO_FEATURE_") {
            if let Some(i) = feature.rfind('_') {
                let name = &feature[..i];
                let value = &feature[i + 1..];
                if let Some(cfg) = configs.get_mut(name) {
                    let Ok(value) = value.parse::<usize>() else {
                        panic!("Invalid value for feature {name}: {value}")
                    };
                    if cfg.seen_feature {
                        panic!("multiple values set for feature {}: {} and {}", name, cfg.value, value);
                    }
                    cfg.value = value;
                    cfg.seen_feature = true;
                }
            }
        }
    }

    // Explicit values override one valid feature selection, never hide conflicting features.
    let prefix = format!("{crate_name}_");
    for (var, value) in &vars {
        if let Some(name) = var.strip_prefix(&prefix) {
            let Some(cfg) = configs.get_mut(name) else {
                panic!("Unknown env var {name}")
            };
            let Ok(value) = value.parse::<usize>() else {
                panic!("Invalid value for env var {name}: {value}")
            };
            cfg.value = value;
            cfg.seen_env = true;
        }
    }

    configs
}

#[cfg(test)]
/// Build-setting regressions run without Cargo environment mutation or target hardware.
mod tests {
    use super::*;

    /// Returns all six orderings of three environment key/value `entries` as owned strings.
    fn permutations(entries: [(&str, &str); 3]) -> Vec<Vec<(String, String)>> {
        [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]]
            .iter()
            .map(|order| {
                order
                    .iter()
                    .map(|&i| (entries[i].0.into(), entries[i].1.into()))
                    .collect()
            })
            .collect()
    }

    /// An explicit environment value overrides one feature regardless of iteration order.
    #[test]
    fn explicit_value_wins_over_one_feature_in_every_order() {
        for vars in permutations([
            ("CARGO_FEATURE_L2CAP_RX_QUEUE_SIZE_4", "1"),
            ("TROUBLE_HOST_L2CAP_RX_QUEUE_SIZE", "7"),
            ("UNRELATED", "ignored"),
        ]) {
            let config = resolve_configs("TROUBLE_HOST", vars);
            assert_eq!(config["L2CAP_RX_QUEUE_SIZE"].value, 7);
            assert!(config["L2CAP_RX_QUEUE_SIZE"].seen_env);
            assert_eq!(config["L2CAP_TX_QUEUE_SIZE"].value, 8);
        }
    }

    /// Two conflicting features always fail, even when an explicit value would override either one.
    #[test]
    fn duplicate_features_rejected_in_every_order_with_override() {
        for vars in permutations([
            ("CARGO_FEATURE_L2CAP_RX_QUEUE_SIZE_4", "1"),
            ("CARGO_FEATURE_L2CAP_RX_QUEUE_SIZE_8", "1"),
            ("TROUBLE_HOST_L2CAP_RX_QUEUE_SIZE", "7"),
        ]) {
            assert!(
                std::panic::catch_unwind(|| resolve_configs("TROUBLE_HOST", vars.clone())).is_err(),
                "accepted {vars:?}"
            );
        }
    }

    /// Unknown names and malformed numbers fail; zero is retained for downstream capacity checks.
    #[test]
    fn invalid_settings_fail_and_zero_remains_explicit() {
        for (name, value) in [
            ("TROUBLE_HOST_UNKNOWN", "1"),
            ("TROUBLE_HOST_L2CAP_RX_QUEUE_SIZE", "invalid"),
            ("CARGO_FEATURE_L2CAP_RX_QUEUE_SIZE_INVALID", "1"),
        ] {
            assert!(
                std::panic::catch_unwind(|| resolve_configs("TROUBLE_HOST", [(name.into(), value.into())])).is_err()
            );
        }
        let config = resolve_configs(
            "TROUBLE_HOST",
            [("TROUBLE_HOST_L2CAP_RX_QUEUE_SIZE".into(), "0".into())],
        );
        assert_eq!(config["L2CAP_RX_QUEUE_SIZE"].value, 0);
        assert!(config["L2CAP_RX_QUEUE_SIZE"].seen_env);
    }
}
